# resposta.tf — o gatilho por severidade, o ticket e o freio de aprovacao

resource "aws_dynamodb_table" "tickets" {
  name         = "${var.projeto}-tickets-seguranca"
  # Sob demanda: o volume de achado e picos imprevisiveis (uma varredura
  # externa gera dezenas de achados no mesmo minuto). Capacidade provisionada
  # aqui e estimar um numero que nao existe.
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "achado_id"

  attribute {
    name = "achado_id"
    type = "S"
  }
}

resource "aws_cloudwatch_event_rule" "achado_critico_ou_alto" {
  name = "${var.projeto}-achado-critico-alto"

  # O MESMO detail-type dispara para achado novo e para achado atualizado —
  # e por isso o filtro de Workflow.Status = NEW e o que evita reabrir um
  # ticket a cada reavaliacao do mesmo achado sem mudanca real.
  event_pattern = jsonencode({
    source        = ["aws.securityhub"]
    "detail-type" = ["Security Hub Findings - Imported"]
    detail = {
      findings = {
        Severity = { Label = ["CRITICAL", "HIGH"] }
        Workflow = { Status = ["NEW"] }
      }
    }
  })
}

resource "aws_cloudwatch_event_target" "para_a_funcao_de_ticket" {
  rule      = aws_cloudwatch_event_rule.achado_critico_ou_alto.name
  target_id = "funcao-ticket"
  arn       = aws_lambda_function.ticket.arn
}

resource "aws_lambda_permission" "eventbridge_invoca" {
  statement_id  = "PermiteEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.ticket.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.achado_critico_ou_alto.arn
}

resource "aws_lambda_function" "ticket" {
  function_name = "${var.projeto}-ticket-seguranca"
  role          = aws_iam_role.ticket_lambda.arn
  handler       = "TicketSeguranca::TicketSeguranca.Function::FunctionHandler"
  runtime       = "dotnet8"
  timeout       = 15
  filename      = data.archive_file.ticket.output_path

  environment {
    variables = {
      TABELA_TICKETS         = aws_dynamodb_table.tickets.name
      ARN_MAQUINA_APROVACAO  = aws_sfn_state_machine.aprovacao.arn
    }
  }
}

resource "aws_sfn_state_machine" "aprovacao" {
  name     = "${var.projeto}-aprovacao-contencao"
  role_arn = aws_iam_role.step_functions.arn
  # Definicao completa na secao seguinte — e o freio para o irreversivel.
  definition = file("${path.module}/aprovacao.asl.json")
}

# Menor privilegio: PutItem/GetItem/UpdateItem restritos a UMA tabela — nao
# dynamodb:* e nao Resource "*". E o habito que o L41 existe para instalar,
# e que copiar uma role generica reabriria.
data "aws_iam_policy_document" "ticket_lambda" {
  statement {
    effect    = "Allow"
    actions   = ["dynamodb:PutItem", "dynamodb:GetItem", "dynamodb:UpdateItem"]
    resources = [aws_dynamodb_table.tickets.arn]
  }
  statement {
    effect    = "Allow"
    actions   = ["states:StartExecution"]
    resources = [aws_sfn_state_machine.aprovacao.arn]
  }
  statement {
    effect = "Allow"
    # PutMetricData nao aceita recurso especifico: e operacao de namespace de
    # metrica, nao de recurso individual. E por isso que o "*" aparece aqui,
    # e em nenhum outro lugar desta policy.
    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ticket_lambda" {
  role   = aws_iam_role.ticket_lambda.id
  policy = data.aws_iam_policy_document.ticket_lambda.json
}

{
  "Comment": "Contencao de achado CRITICAL: para numa aprovacao antes de qualquer acao irreversivel",
  "StartAt": "AguardaAprovacao",
  "States": {
    "AguardaAprovacao": {
      "Type": "Task",
      "Resource": "arn:aws:states:::sns:publish.waitForTaskToken",
      "Parameters": {
        "TopicArn": "${var.arn_topico_aprovacao}",
        "Message.$": "$",
        "MessageAttributes": {
          "TaskToken": { "DataType": "String", "StringValue.$": "$$.Task.Token" }
        }
      },
      "TimeoutSeconds": 3600,
      "Next": "Decisao",
      "Catch": [
        { "ErrorEquals": ["States.Timeout"], "Next": "AprovacaoExpirou" }
      ]
    },
    "Decisao": {
      "Type": "Choice",
      "Choices": [
        { "Variable": "$.aprovado", "BooleanEquals": true, "Next": "ExecutaContencao" }
      ],
      "Default": "AprovacaoNegada"
    },
    "ExecutaContencao": {
      "Type": "Succeed"
    },
    "AprovacaoNegada": {
      "Type": "Fail",
      "Error": "AnalistaRejeitou",
      "Cause": "Analista revisou o achado e decidiu que a acao nao deve ser executada"
    },
    "AprovacaoExpirou": {
      "Type": "Fail",
      "Error": "SemRespostaEmUmaHora",
      "Cause": "Ninguem aprovou nem rejeitou dentro do prazo — o achado continua ABERTO no ticket"
    }
  }
}

// Function.cs — o Lambda que transforma achado em ticket com prazo

using Amazon.Lambda.Core;
using Amazon.DynamoDBv2;
using Amazon.DynamoDBv2.Model;
using Amazon.StepFunctions;
using Amazon.StepFunctions.Model;
using System.Text.Json;

[assembly: LambdaSerializer(typeof(Amazon.Lambda.Serialization.SystemTextJson.DefaultLambdaJsonSerializer))]

namespace TicketSeguranca;

public record Severidade(string Label);
public record Achado(string Id, Severidade Severity, List<string> Types, List<object> Resources);
public record Findings(List<Achado> Findings);
public record EventoEventBridge(Findings Detail);

public class Function
{
    // SLA por severidade — nao existe UM prazo, existe uma tabela. Achado
    // LOW e INFORMATIONAL nem chegam aqui: o padrao do EventBridge ja os
    // filtra antes de esta funcao ser invocada.
    private static readonly Dictionary<string, TimeSpan> PrazoPorSeveridade = new()
    {
        ["CRITICAL"] = TimeSpan.FromMinutes(15),
        ["HIGH"]     = TimeSpan.FromHours(1),
    };

    private readonly AmazonDynamoDBClient _dynamo = new();
    private readonly AmazonStepFunctionsClient _stepFunctions = new();
    private readonly string _tabela = Environment.GetEnvironmentVariable("TABELA_TICKETS")!;
    private readonly string _maquinaAprovacao = Environment.GetEnvironmentVariable("ARN_MAQUINA_APROVACAO")!;

    public async Task FunctionHandler(EventoEventBridge evento, ILambdaContext contexto)
    {
        foreach (var achado in evento.Detail.Findings)
        {
            var agora = DateTimeOffset.UtcNow;
            var prazo = agora + PrazoPorSeveridade[achado.Severity.Label];

            // Idempotencia CORRETA: a chave inclui a severidade atual, nao
            // so o identificador do achado. Um achado que escala de MEDIUM
            // para CRITICAL muda de chave e gera um SEGUNDO registro com
            // prazo mais curto — em vez de esta funcao ignorar em silencio
            // a atualizacao porque "esse achado ja tem ticket". E o defeito
            // que a secao de falhas deste modulo provoca de proposito.
            var chave = $"{achado.Id}#{achado.Severity.Label}";

            await _dynamo.PutItemAsync(new PutItemRequest
            {
                TableName = _tabela,
                Item = new Dictionary<string, AttributeValue>
                {
                    ["achado_id"]  = new AttributeValue { S = chave },
                    ["severidade"] = new AttributeValue { S = achado.Severity.Label },
                    ["criado_em"]  = new AttributeValue { S = agora.ToString("O") },
                    ["prazo"]      = new AttributeValue { S = prazo.ToString("O") },
                    ["status"]     = new AttributeValue { S = "ABERTO" },
                    ["tipo"]       = new AttributeValue { S = achado.Types.FirstOrDefault() ?? "desconhecido" },
                },
                // Nao sobrescreve um ticket ja aberto para a MESMA chave —
                // mas uma chave nova (severidade diferente) sempre grava.
                ConditionExpression = "attribute_not_exists(achado_id)",
            });

            // So achado CRITICAL de um tipo conhecido como automatizavel
            // entra no fluxo de aprovacao. Esta funcao NUNCA executa a
            // contencao: ela apenas inicia a maquina de estados que vai
            // parar numa aprovacao humana antes de qualquer acao.
            if (achado.Severity.Label == "CRITICAL" && EhAutomatizavel(achado))
            {
                await _stepFunctions.StartExecutionAsync(new StartExecutionRequest
                {
                    StateMachineArn = _maquinaAprovacao,
                    Input = JsonSerializer.Serialize(new { achado.Id, achado.Resources }),
                });
            }
        }
    }

    // Lista curta e explicita, de proposito: contencao automatizada so se
    // propoe para tipos de achado onde a acao (isolar instancia, revogar
    // credencial) e conhecida e a equipe ja decidiu que quer o fluxo de
    // aprovacao para eles. Tipo fora da lista vira ticket, sem fluxo de
    // contencao — alguem decide manualmente o proximo passo.
    private static bool EhAutomatizavel(Achado achado) =>
        achado.Types.Any(t => t.StartsWith("CryptoCurrency") || t.StartsWith("UnauthorizedAccess"));
}
